-- WrathUnleashed MAIN realm: undo the Brawl world changes (brawl_world.sql + brawl_world_2.sql) on a world
-- database that once ran the Brawl profile. GENERATED by gen_unbrawl.py from the stock world data of the realm's
-- core (mod-playerbots/azerothcore-wotlk 3f2969dd, data/sql/base/db_world). Applies to acore_world.
-- Safe to run again and safe on a database that never ran Brawl: every statement only touches rows that still
-- carry a Brawl value, and only puts back stock values. It never touches characters.
--
--   1. class spells / professions / mounts Brawl taught at character creation (Note 'brawl', 'brawl2')
--   2. Brawl's starter bags and class kits (playercreateinfo_item; stock has none of these items)
--   3. start positions: every race/class back to its stock start (Brawl moved all of them to Dalaran)
--   4. dual spec costs 1000 gold again at the class trainer (stock BoxMoney)
--   5. vendor items cost and sell for gold again (stock BuyPrice / SellPrice), only where Brawl zeroed both
--   6. honor / arena / badge / token costs back on vendor rows (stock npc_vendor ExtendedCost rows)
-- Not undone: nothing else (modern_combos.sql stays; it is part of the main realm).

-- 1.
DELETE FROM `playercreateinfo_spell_custom` WHERE `Note` IN ('brawl', 'brawl2');
DELETE FROM `playercreateinfo_skills` WHERE `comment` = 'brawl';

-- 2.
DELETE FROM `playercreateinfo_item` WHERE `itemid` IN
(41599,5175,5176,5177,5178,21340,41165,41164,17020,17031,17032,44615,44605,21177,17030);

-- 3. Stock rows by (race, class); combos that only mod-arac / modern_combos add (no stock row) take their race's
--    stock start (Death Knights: the race's Death Knight start, Acherus).
DROP TABLE IF EXISTS `ov_stock_start`;
CREATE TABLE `ov_stock_start` (`race` TINYINT UNSIGNED, `class` TINYINT UNSIGNED, `map` SMALLINT UNSIGNED, `zone` INT UNSIGNED, `x` FLOAT, `y` FLOAT, `z` FLOAT, `o` FLOAT, PRIMARY KEY (`race`, `class`));
UPDATE `playercreateinfo` p JOIN `ov_stock_start` s ON s.`race` = p.`race` AND s.`class` = p.`class`
SET p.`map` = s.`map`, p.`zone` = s.`zone`, p.`position_x` = s.`x`, p.`position_y` = s.`y`, p.`position_z` = s.`z`, p.`orientation` = s.`o`
WHERE p.`map` = 571 AND p.`zone` = 4395;
-- combos without a stock row: the race's start (lowest stock non-DK class), or the race's DK start for DKs
UPDATE `playercreateinfo` p
JOIN (SELECT s.* FROM `ov_stock_start` s JOIN (SELECT `race`, MIN(`class`) AS c FROM `ov_stock_start` WHERE `class` <> 6 GROUP BY `race`) m
      ON m.`race` = s.`race` AND m.c = s.`class`) s ON s.`race` = p.`race`
SET p.`map` = s.`map`, p.`zone` = s.`zone`, p.`position_x` = s.`x`, p.`position_y` = s.`y`, p.`position_z` = s.`z`, p.`orientation` = s.`o`
WHERE p.`map` = 571 AND p.`zone` = 4395 AND p.`class` <> 6;
UPDATE `playercreateinfo` p JOIN `ov_stock_start` s ON s.`race` = p.`race` AND s.`class` = 6
SET p.`map` = s.`map`, p.`zone` = s.`zone`, p.`position_x` = s.`x`, p.`position_y` = s.`y`, p.`position_z` = s.`z`, p.`orientation` = s.`o`
WHERE p.`map` = 571 AND p.`zone` = 4395 AND p.`class` = 6;
DROP TABLE `ov_stock_start`;

-- 4.
UPDATE `gossip_menu_option` SET `BoxMoney` = 10000000 WHERE `MenuID` = 0 AND `OptionID` = 16 AND `OptionType` = 18 AND `BoxMoney` = 0;
UPDATE `gossip_menu_option` SET `BoxMoney` = 10000000 WHERE `MenuID` = 6647 AND `OptionID` = 2 AND `OptionType` = 18 AND `BoxMoney` = 0;
UPDATE `gossip_menu_option` SET `BoxMoney` = 10000000 WHERE `MenuID` = 10371 AND `OptionID` = 0 AND `OptionType` = 18 AND `BoxMoney` = 0;

-- 5. Stock prices of every item a stock vendor sells; only rows where both prices are still 0 change.
DROP TABLE IF EXISTS `ov_stock_price`;
CREATE TABLE `ov_stock_price` (`entry` INT UNSIGNED PRIMARY KEY, `buy` BIGINT, `sell` INT UNSIGNED);
UPDATE `item_template` i JOIN `ov_stock_price` s ON s.`entry` = i.`entry`
SET i.`BuyPrice` = s.`buy`, i.`SellPrice` = s.`sell` WHERE i.`BuyPrice` = 0 AND i.`SellPrice` = 0;
DROP TABLE `ov_stock_price`;

-- 6. Brawl turned each token-cost row into a free row (ExtendedCost 0) or deleted it. Remove the free rows that
--    stock does not have, then put the stock token-cost rows back.
DROP TABLE IF EXISTS `ov_stock_vendor`;
CREATE TABLE `ov_stock_vendor` (`entry` INT UNSIGNED, `slot` SMALLINT, `item` INT, `maxcount` INT UNSIGNED, `incrtime` INT UNSIGNED, `ExtendedCost` INT UNSIGNED, `vb` INT NULL, `stock_free` TINYINT, PRIMARY KEY (`entry`, `item`, `ExtendedCost`));
DELETE v FROM `npc_vendor` v JOIN (SELECT DISTINCT `entry`, `item` FROM `ov_stock_vendor` WHERE `stock_free` = 0) s
  ON s.`entry` = v.`entry` AND s.`item` = v.`item` WHERE v.`ExtendedCost` = 0;
SELECT `entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `vb` FROM `ov_stock_vendor`;
DROP TABLE `ov_stock_vendor`;
